{
  "status": "NEEDS_IMPROVEMENT",
  "core_findings": [
    "Electronics has the weakest measured training separation: 9.38% negative-over-positive rankings versus 0.23–3.91% elsewhere, with 1,280 observations/category. Margins depend on score scale and supplied negatives; they do not measure validation HR@10.",
    "The prespecified frequency-matched old-minus-random contrast is positive for Movies (0.1254, 95% CI [0.0221, 0.2329]) and CDs (0.1356, [0.0405, 0.2297]); Industrial and Electronics intervals include zero. Old substitutions are less disruptive than random substitutions in those two categories, without establishing that old history is harmful."
  ],
  "key_implications": [
    "Intervention estimates cover 111/99/91/228 unique users across Movies/Industrial/Electronics/CDs; no no-op failures, substitution abstentions, or nonfinite margins were reported, but short-history old-lag contrasts are unavailable.",
    "Embedding alignment scores of 0.5062–0.5245 indicate near-zero mean pairwise cosine alignment, not recommendation diversity; observed padding activations are zero, while locality and outside-field invariance remain uncertified.",
    "User-bootstrap intervals condition on the checkpoint and protocol, exclude training/search uncertainty, and provide no simultaneous guarantees; validation interventions and macro uncertainty are missing, so selection remains pinned host macro validation HR@10."
  ],
  "evidence": {
    "headline_metrics": {
      "Electronics:pos_neg_margin_p10": 0.1209,
      "Electronics:pos_neg_neg_beats_pos_rate": 0.0938,
      "Movies_and_TV:frequency_matched/old_minus_random": 0.1254,
      "CDs_and_Vinyl:frequency_matched/old_minus_random": 0.1356
    },
    "brief_metric_read": {
      "Electronics:pos_neg_margin_p10": "Lower-tail training separation is close to zero on the measured score scale.",
      "Industrial_and_Scientific:frequency_matched/old_minus_random": "0.0273; CI [-0.0438, 0.0898] includes zero.",
      "Electronics:frequency_matched/old_minus_random": "0.0233; CI [-0.0162, 0.0637] includes zero."
    }
  }
}
